              hints: ['flow filter addr.', '<code>diagnose debug flow filter addr ____</code>'], steps: ['diagnose debug flow filter addr 10.64.10.50'],
              check: s => s.ev.ran(/^diagnose debug flow filter (s?addr) 10\.64\.10\.50$/),
